import React from "react";

const SlotCard = ({ slot }) => {
  const isOccupied = slot.status === "occupied";
  const lastActivity = slot.time
    ? `${Math.floor((Date.now() - new Date(slot.time)) / 60000)}m ago`
    : "—";

  return (
    <div className={`slot-card ${isOccupied ? "occupied" : "vacant"}`}>
      <div className="slot-top">
        <div className="slot-icon-box">{isOccupied ? "🚗" : "🅿️"}</div>
        <div className="slot-title">
          <div className="slot-name">Slot {slot.slot}</div>
          <div className="slot-plate">Plate: {slot.plate || "-"}</div>
        </div>
        <div className={`status-badge ${isOccupied ? "badge-occupied" : "badge-vacant"}`}>
          {isOccupied ? "Occupied" : "Vacant"}
        </div>
      </div>

      <div className="slot-bottom">
        <div className="last-activity">⏱ Last activity: {lastActivity}</div>
      </div>
    </div>
  );
};

export default SlotCard;
